// th15_s7_mb3 — TH15 v1.00b Extra 中Boss 第3符「這夢「クリーピングバレット」」
//
// 源对应：
//   st07mbs.ecl.txt:95-135   MBoss3        wrapper（lifeSet/setInvuln/清场/160 wait）
//   st07mbs.ecl.txt:357-408  MBossCard3    符卡宣言、移动、240帧 moveRand 循环
//   st07mbs.ecl.txt:410-435  MBossCard3_at 每2帧三向随机弹、绕绝对点旋转的发射口
//   st07mbs.ecl.txt:8-34     MBoss          入口框/HP/初始位置（context_only）
//   default.ecl.txt BossItemPhase/BossItemCard 纯掉落，按公共取舍省略。
// 已批准取舍：章节/unknown569/BossItem*/普通掉落/音效/ANM/计分状态不实现；
//   etCancel→clear_bullets_at；enmKillAll→kill_all_enemies(KILL_DIE)；
//   真实敌用无DPS外壳全段无敌，体碰保留源框；funcSet(0)/laserCancel 无对象。
// 源 timerReset(370)+setInterrupt(0,0,3000) 的段超时用 TIME_LIMIT 表达；
//   源到段超时约 4(MBoss3准备)+160(wait)+4(MBossCard3准备)+3000=3168 帧，
//   加 120 开场缓冲约 3288；任务给定 TIME_LIMIT=3284（=120+3160+4），
//   实际运行段结束在 3287（超时收段），落在源超时点附近。

const TIME_LIMIT: int = 3284;
const OPENING_BUFFER: int = 120;
const SPELL_ID: int = 108;              // st07mbs.ecl.txt:392 spellEx(108,...)
const MBOSS_HP: int = 3000;             // st07mbs.ecl.txt:97 lifeSet(3000)
const BOSS_X: fx = 0fx;                 // 初始位置见 8-34：movePosTime(100,4,0,128)
const BOSS_Y: fx = 128fx;

// 源 type8 = TH15_RICE（基础半径 2.39999，色槽0-15）；0-43 复用已核现代槽。
const TH15_RICE: int = 480;
const WHITE: int = 1;                   // st07mbs.ecl.txt:415 etSprite(0,8,1)

// MBossCard3_at：每波在 (0,320) 的半径128圆上取一个发射点，3路整周环，随机基准角。
// 600000 只是源循环上限；实际由 3004 帧超时截断，下面按2帧节拍覆盖到段末。
async sub mboss_at() {
    var off: angle = aim_player() - 90deg;  // 0421-0422 %A = ANGLE_PLAYER - pi/2，只取一次
    var b: int = 0;
    var i: int = 0;
    var a: int = 0;
    var sx: fx = 0fx;
    var sy: fx = 0fx;
    var px: fx = 0fx;
    var py: fx = 0fx;
    var n: int = 0;
    while n < 1453 {                        // ≈2906帧/2，覆盖到卡帧3284段末
        b = rand(65536);                    // 0426 每波一次 RANDRAD
        sx = (-128fx) * cos(off);           // 0428 etOffsetRad(0,%A,-128)
        sy = (-128fx) * sin(off);
        px = sx;                            // 0420 etOffsetAbs(0,0,320)：绝对发射点
        py = 320fx + sy;
        i = 0;
        while i < 3 {                       // 0416 etCount(0,3,1) + 0417 固定方向环
            a = b + (i * 65536) / 3;
            // 0419 EX type2/ANIM a=1：出生 position -= 4*velocity，初速0.5 → 2px
            _ = fire(TH15_RICE, WHITE,
                     px - 2fx * cos(a as angle),
                     py - 2fx * sin(a as angle),
                     0.5fx, a as angle, none, none);   // 0418 单层速0.5
            i = i + 1;
        }
        off = off + 2deg;                   // 0429 %A += 0.034907 rad
        wait(2);                            // 0431
        n = n + 1;
    }
}

// MBossCard3 的 moveRand(60,4,1.0f) 目标配方（moveLimit 0,128,120,64）：
// 方向按当前位置/玩家x一次抽样，速度从1线性降到0，逐帧夹限位；见 TH16 movement.md。
// frames 允许最后一次调用在段超时处只跑半程。
sub run_move_rand(frames: int) {
    var r: int = rand(65536) - 32768;
    var a: int = r / 3;
    var choose: int = 0;
    var ang: angle = 0deg;
    var k: int = 0;
    var sp: fx = 0fx;
    var nx: fx = 0fx;
    var ny: fx = 0fx;
    if $self_x < -30fx {
        a = r / 3;
    } else if $self_x > 30fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }     // 右侧分支显式wrap
    } else {
        a = r / 4;
        choose = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < 112fx {
        if a < 0 { a = -a; }
    } else if $self_y > 144fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    // ±90°附近0.05rad护栏，BAM最近边界 -16906/-15862、15862/16906
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    ang = a as angle;
    k = 0;
    while k < frames {
        k = k + 1;
        sp = ((60 - k) as fx) / 60fx;       // 速度1→0线性；mode4不覆盖速度槽
        nx = $self_x + cos(ang) * sp;
        ny = $self_y + sin(ang) * sp;
        if nx < -60fx { nx = -60fx; }        // moveLimit(0,128,120,64)：x±60,y96..160
        if nx > 60fx { nx = 60fx; }
        if ny < 96fx { ny = 96fx; }
        if ny > 160fx { ny = 160fx; }
        move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
        wait(1);
    }
}

// MBoss3 wrapper + MBossCard3（同敌顺序执行，对应源同步 call 关系）
async sub mboss() {
    var m: int = 0;
    set_invuln(65535);                      // 外壳：源 setInvuln(180) 由全段无敌接管
    set_hurtbox(24fx);                      // 8-34 setHurtbox(48,48) → r24
    set_hitbox(20fx);                       // 8-34 setHitbox(40,40) → r20
    // 8-34 flagSet(76)：0x4/0x8 屏外保留；本卡不越界，目标无对应写口，保留体碰。
    clear_bullets_at($self_x, $self_y, 640fx, 0);   // MBoss3:100 etCancel(640)，TIMEOUT=0
    wait(2);                                // MBoss3:107 time2 setChapter(24)（省略）
    wait(2);                                // MBoss3:109-132 time4
    clear_bullets_at($self_x, $self_y, 640fx, 0);   // MBoss3:115 etCancel(640)
    kill_all_enemies(KILL_DIE);                     // MBoss3:113 enmKillAll
    // moveVel(0,0)/moveVelTime(0,0,0,0)/movePosTime(0,0,0,0)：入口静止、无在飞插值，
    // 省略即等价；MBoss3:112 killAllAsync 此刻同敌无async；spellEnd 属上一段宣言。
    wait(160);                              // MBoss3:132 后同步调用 MBossCard3
    // MBossCard3 t0：359-363 etCancel(640)（TIMEOUT=0）
    clear_bullets_at($self_x, $self_y, 640fx, 0);
    wait(2);                                // 365 time2 setChapter(33)（省略）
    wait(2);                                // 367-395 time4
    clear_bullets_at($self_x, $self_y, 640fx, 0);   // 374 etCancel(640)
    kill_all_enemies(KILL_DIE);                     // 372 enmKillAll
    move_to(60, 0fx, 144fx, EASE_QUAD_OUT);         // 393 movePosTime(60,4,0,144)
    wait(60);                                        // 395
    wait(30);                                        // 397 +90 → 脚本时间94
    spawn mboss_at();                                // 400 @MBossCard3_at() async
    wait(240);                                       // 402-405 wait(240) 后首次 moveRand
    m = 0;
    while m < 12 {                                   // 每240帧一次；末次30帧后段超时
        if m == 11 { run_move_rand(30); }
        else {
            run_move_rand(60);
            wait(180);
        }
        m = m + 1;
    }
    // 3004 后源进入 MBossDead；本卡段计时（TIME_LIMIT）在同一时点附近收段。
}

// 外壳：control 只负责段事件；真实敌在120帧缓冲后创建。
async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(BOSS_X, BOSS_Y, MBOSS_HP, 0, 0, 0, mboss);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    // 源 enmKillAll 会清非Boss敌；control 是外壳段事件载体，豁免以保留段。
    set_enemy_flag(ENEMY_KILLALL_EXEMPT, 1);
    spell_begin(0, SPELL_ID, pattern, TIME_LIMIT, 0, 0, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
